import sys, json, os, re, argparse

def parse_path(expr):
    parts = re.findall(r'\.([a-zA-Z0-9_.-]+)|\[([0-9]+)\]', expr)
    path = []
    for p1, p2 in parts:
        if p1: path.append(p1)
        elif p2: path.append(int(p2))
    return path

def get_value(data, path):
    curr = data
    for p in path:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        elif isinstance(curr, list) and isinstance(p, int) and p < len(curr):
            curr = curr[p]
        else:
            return None
    return curr

def set_value(data, path, val):
    curr = data
    for p in path[:-1]:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        elif isinstance(curr, list) and isinstance(p, int) and p < len(curr):
            curr = curr[p]
        else:
            # simple creation not fully supported but enough for existing paths
            return
    curr[path[-1]] = val

def evaluate(data, expr):
    expr = expr.strip()
    is_array_wrapped = False
    if expr.startswith("[") and expr.endswith("]"):
        is_array_wrapped = True
        expr = expr[1:-1].strip()

    if "=" in expr and "==" not in expr:
        left, right = expr.split("=", 1)
        left = left.strip()
        right = right.strip()
        path = parse_path(left)

        if right.startswith('"') and right.endswith('"'):
            val = right[1:-1]
        elif right.startswith("strenv("):
            env_var = right[7:-1]
            val = os.environ.get(env_var, "")
        else:
            val = right

        set_value(data, path, val)
        return data
    else:
        if "|" in expr:
            left, right = expr.split("|", 1)
            left = left.strip()
            right = right.strip()
            if left.endswith("[]"):
                path = parse_path(left[:-2])
                arr = get_value(data, path)
                if right.startswith("select("):
                    cond = right[7:-1]
                    if "==" in cond:
                        c_left, c_right = cond.split("==", 1)
                        c_left = c_left.strip()
                        c_right = c_right.strip().strip('"')
                        c_path = parse_path(c_left)
                        res = []
                        if arr:
                            for item in arr:
                                if get_value(item, c_path) == c_right:
                                    res.append(item)
                        return res
            return []
        else:
            path = parse_path(expr)
            return get_value(data, path)

if __name__ == "__main__":
    import pprint
    data = {"a": {"b": [{"c": "cool"}]}}
    print(evaluate(data, ".a.b[0].c"))
    print(evaluate(data, ".a.b[0].c = \"foo\""))

    data2 = {"items": [{"type": "fruit", "name": "apple"}, {"type": "vegetable", "name": "carrot"}]}
    print(evaluate(data2, ".items[] | select(.type == \"fruit\")"))
