def parse_yaml(yaml_text):
    lines = yaml_text.splitlines()
    def parse_block(start_idx, indent):
        obj = None
        idx = start_idx
        while idx < len(lines):
            line = lines[idx]
            stripped = line.strip()
            if not stripped or stripped.startswith('#') or stripped == '---':
                idx += 1
                continue

            curr_indent = len(line) - len(line.lstrip(' '))
            if curr_indent < indent:
                break

            if stripped.startswith('- '):
                if obj is None: obj = []
                val_str = stripped[2:].strip()
                if not val_str:
                    val, new_idx = parse_block(idx + 1, curr_indent + 2)
                    obj.append(val)
                    idx = new_idx
                elif ':' in val_str:
                    k, v = val_str.split(':', 1)
                    k, v = k.strip(), v.strip()
                    item_dict = {k: parse_val(v)}
                    obj.append(item_dict)
                    idx += 1
                else:
                    obj.append(parse_val(val_str))
                    idx += 1
            elif ':' in stripped:
                if obj is None: obj = {}
                k, v = stripped.split(':', 1)
                k, v = k.strip(), v.strip()
                if isinstance(obj, list):
                    if len(obj) > 0 and isinstance(obj[-1], dict):
                        if not v:
                            val, new_idx = parse_block(idx + 1, curr_indent + 2)
                            obj[-1][k] = val
                            idx = new_idx
                        else:
                            obj[-1][k] = parse_val(v)
                            idx += 1
                    else:
                        raise ValueError("Unexpected key-value in list")
                else:
                    if not v:
                        val, new_idx = parse_block(idx + 1, curr_indent + 2)
                        obj[k] = val
                        idx = new_idx
                    else:
                        obj[k] = parse_val(v)
                        idx += 1
            else:
                idx += 1
        return obj, idx

    def parse_val(v):
        if v.startswith('"') and v.endswith('"'): return v[1:-1]
        if v.startswith("'") and v.endswith("'"): return v[1:-1]
        if v.isdigit(): return int(v)
        if v == 'true': return True
        if v == 'false': return False
        if v == 'null': return None
        return v

    res, _ = parse_block(0, 0)
    return res

