def to_yaml(data, indent=0, is_in_list=False):
    if isinstance(data, dict):
        res = []
        for i, (k, v) in enumerate(data.items()):
            prefix = ""
            if is_in_list and i == 0:
                prefix = ""
            else:
                prefix = "  " * indent

            if isinstance(v, (dict, list)):
                if not v:
                    res.append(f"{prefix}{k}: []" if isinstance(v, list) else f"{prefix}{k}: {{}}")
                else:
                    res.append(f"{prefix}{k}:")
                    if isinstance(v, list):
                        res.append(to_yaml(v, indent))
                    else:
                        res.append(to_yaml(v, indent + 1))
            else:
                res.append(f"{prefix}{k}: {v}")
        return "\n".join(res)
    elif isinstance(data, list):
        res = []
        for i in data:
            if isinstance(i, (dict, list)):
                if not i:
                    res.append(f"{'  ' * indent}- []" if isinstance(i, list) else f"{'  ' * indent}- {{}}")
                else:
                    item_str = to_yaml(i, indent + 1, is_in_list=True)
                    res.append(f"{'  ' * indent}- {item_str}")
            else:
                res.append(f"{'  ' * indent}- {i}")
        return "\n".join(res)
    else:
        return str(data)

