            elif len(arg) > 2:
                flags['o'] = 'json' if arg[2:] == 'j' else 'yaml'
            else:
                idx += 1
                if idx < len(args): flags['o'] = args[idx]
            idx += 1
        elif arg.startswith('-p'):
            if '=' in arg:
                flags['p'] = arg.split('=')[1]
            else:
                idx += 1
                if idx < len(args): flags['p'] = args[idx]
            idx += 1
        elif arg.startswith('-'):
            if arg not in ('-r', '--unwrapScalar', '-C', '--colors', '-M', '--no-colors', '-N', '--no-doc', '-0', '--nul-output'):
                print_usage(f"unknown flag: {arg}")
                sys.exit(1)
            idx += 1
        else:
            if expr is None:
                expr = arg
            else:
                files.append(arg)
            idx += 1

    # Format detection logic
    # if out format is yaml but file is json, default to json unless forced?
    # yq default output format is yaml usually, but if auto, let's keep yaml unless forced json
    if not files and not sys.stdin.isatty():
        content = sys.stdin.read()
        if flags['p'] == 'xml':
            data = parse_xml(content)
        else:
            data = parse_yaml(content)
        res = evaluate(data, expr)
        if isinstance(res, list) and not expr.startswith("[") and ("[]" in expr or "select(" in expr):
            for i, item in enumerate(res):
                print(format_output(item, flags['o'], flags['P']))
        else:
            print(format_output(res, flags['o'], flags['P']))
    else:
        if not files and expr is not None and not flags['n']:
            # might be just reading from stdin
            content = sys.stdin.read()
            if flags['p'] == 'xml':
                data = parse_xml(content)
            else:
                data = parse_yaml(content)
            res = evaluate(data, expr)
            if isinstance(res, list) and not expr.startswith("[") and ("[]" in expr or "select(" in expr):
                for i, item in enumerate(res):
                    print(format_output(item, flags['o'], flags['P']))
            else:
                print(format_output(res, flags['o'], flags['P']))
        elif flags['n']:
            res = evaluate({}, expr)
            print(format_output(res, flags['o'], flags['P']))
        else:
            for f in files:
                with open(f, 'r') as file:
                    content = file.read()

                input_fmt = flags['p']
                if input_fmt == 'auto':
                    if f.endswith('.xml'):
                        input_fmt = 'xml'
                    elif f.endswith('.json'):
                        input_fmt = 'json'

                out_fmt = flags['o']
                if out_fmt == 'yaml' and f.endswith('.json'):
                    out_fmt = 'json' # simplistic fallback, yq usually defaults to YAML output

                if input_fmt == 'xml':
                    data = parse_xml(content)
                elif input_fmt == 'json':
                    try:
                        data = json.loads(content)
                    except:
                        data = parse_yaml(content)
                else:
                    data = parse_yaml(content)

                res = evaluate(data, expr)

                if flags['i']:
                    with open(f, 'w') as file:
                        if isinstance(res, list) and not expr.startswith("[") and ("[]" in expr or "select(" in expr):
                            for i, item in enumerate(res):
                                file.write(format_output(item, out_fmt, flags['P']) + '\n')
                        else:
                            file.write(format_output(res, out_fmt, flags['P']) + '\n')
                else:
                    if isinstance(res, list) and not expr.startswith("[") and ("[]" in expr or "select(" in expr):
                        for i, item in enumerate(res):
                            print(format_output(item, flags['o'], flags['P']))
                    else:
                        print(format_output(res, flags['o'], flags['P']))

